const getSettingsManagerFn = () => settingsManager;
const ragHandler = useMemo(() => createRagHandler({
  setChatHistory,
  getSettingsManager: getSettingsManagerFn,
  ragListOffset,
  setRagListOffset,
  setRagInputAction,
  setRagInputPrompt,
  clearInput,
}), [setChatHistory, settingsManager, ragListOffset, setRagListOffset, setRagInputAction, setRagInputPrompt, clearInput]);

update_md5_6253ec053762a8ffe5c81e683411b.content_md5_6253ec053762a8ffe5c81e683411:
const getSettingsManagerFn = () => settingsManager;
const clearInputRef = useRef<() => void>(() => {});
const ragHandlerRef = useRef<ReturnType<typeof createRagHandler> | null>(null);

useEffect(() => {
  ragHandlerRef.current = createRagHandler({
    setChatHistory,
    getSettingsManager: getSettingsManagerFn,
    ragListOffset,
    setRagListOffset,
    setRagInputAction,
    setRagInputPrompt,
    clearInput: () => clearInputRef.current(),
  });
}, [setChatHistory, settingsManager, ragListOffset, setRagListOffset, setRagInputAction, setRagInputPrompt]);

